/** The static data generated by `pnpm build:data`, loaded once. */
import {
  decodeHill,
  parseScoringConfig,
  type AttributionsFile,
  type Hill,
  type HillList,
  type HillsFile,
  type ScoringConfig,
  type Zone,
  type ZonesFile,
} from '@atmos/engine';

export interface StaticData {
  hills: Hill[];
  hillsByNumber: Map<number, Hill>;
  lists: HillList[];
  zones: Zone[];
  zonesById: Map<string, Zone>;
  config: ScoringConfig;
  attributions: AttributionsFile['attributions'];
  hillsSource: string;
}

async function getJson<T>(path: string): Promise<T> {
  const res = await fetch(path);
  if (!res.ok)
    throw new Error(`Couldn't load ${path} (${res.status}). Was \`pnpm build:data\` run?`);
  return (await res.json()) as T;
}

let loading: Promise<StaticData> | null = null;

export function loadStaticData(): Promise<StaticData> {
  loading ??= (async () => {
    const [hillsFile, zonesFile, profiles, attributions] = await Promise.all([
      getJson<HillsFile>('/data/hills.json'),
      getJson<ZonesFile>('/data/zones.json'),
      getJson<unknown>('/data/profiles.json'),
      getJson<AttributionsFile>('/data/attributions.json'),
    ]);
    const hills = hillsFile.hills.map(decodeHill);
    return {
      hills,
      hillsByNumber: new Map(hills.map((h) => [h.number, h])),
      lists: hillsFile.lists,
      zones: zonesFile.zones,
      zonesById: new Map(zonesFile.zones.map((z) => [z.id, z])),
      config: parseScoringConfig(profiles),
      attributions: attributions.attributions,
      hillsSource: hillsFile.source,
    };
  })();
  return loading;
}

/** Profiles judged at each summit, rather than once for the whole zone at valley level. */
export const SUMMIT_PROFILES = new Set(['walking', 'inversion']);

export const MODEL_LABELS: Record<string, string> = {
  ukmo_seamless: 'Met Office',
  ukmo_uk_deterministic_2km: 'Met Office UKV',
  ukmo_global_deterministic_10km: 'Met Office Global',
  ecmwf_ifs025: 'ECMWF',
  icon_seamless: 'DWD ICON',
};

export const modelLabel = (id: string) => MODEL_LABELS[id] ?? id;
